  const f=ui.pitchF2||'P';let h=`<div class="mktabs4 five">${[['P','투수단'],['B','타자단'],['D','수비/주루'],['S','상태'],['C','계약']].map(x=>`<button class="${f===x[0]?'on':''}" onclick="UI.pitchF2('${x[0]}')">${x[1]}</button>`).join('')}</div>`;
