function renderFinMock(ut){const I=ut.league==='KR'?SL.budgetInfo():{wage:SL.payroll(ut),pay:SL.payroll(ut),wageLeft:0,xfer:0,xferLeft:0};const f=ut.fin;const pay=SL.payroll(ut);const pct=Math.min(100,Math.round(I.pay/Math.max(1,I.wage)*100));const prev=(S.history||[]).slice(-1)[0];const pf=prev&&prev.user&&prev.user.fin;const d=mkDate();
  const ps=ut.roster.concat(ut.dev).map(id=>S.players[id]).filter(p=>p&&p.contract);const s0=S.phase==='season'?S.season:S.season+1;const rows=[0,1,2].map(i=>{const sal=ps.reduce((a,p)=>a+(p.contract.years>i?p.contract.salary:0),0);return [mkYear(s0+i),sal,ps.filter(p=>p.contract.years>i).length];}).filter(r=>r[2]>0);
  const inc=[['🎟 입장 수입','tickets'],['📺 메인 스폰서','sponsor'],['🤝 광고 · 광고 수수료',null,(x)=>(x.ads||0)+(x.endorse||0)],['🏆 리그 배당 · 지원금',null,x=>(x.dividend||0)+(x.grant||0)],['💱 선수 판매','sales']];const out=[['👥 선수단 연봉 지출','salary'],['🏢 구단 운영비 (시설·육성 등)',null,x=>(x.facility||0)+(x.scout||0)+(x.staff||0)+(x.dispatch||0)+(x.other||0)],['💼 영입·계약금','buys']];
  const val=(x,k,fn)=>fn?fn(x):(x[k]||0);const cmp=(k,fn,neg)=>{if(!pf)return '';const a=val(f,k,fn),b=val(pf,k,fn);if(!b)return '<span class="muted">-</span>';const dd=a-b;if(!dd)return '<span class="muted">→ 동일</span>';const pc=Math.round(dd/b*100);return `<span class="${(neg?dd<=0:dd>=0)?'ok':'o'}">${dd>=0?'▲ +':'▼ '}${Ms(Math.abs(dd))} (${pc>=0?'+':''}${pc}%)</span>`;};
  let h=`<div class="mkh"><span class="t">구단 재정</span><span class="r small">📅 시즌 ${mkYear()}<br>${d.m}월 ${d.d}일 (${d.w})</span></div>`;
  h+=`<div class="fin3"><div><span class="ic">💵</span><small>현금</small><b>${Ms(ut.cash)}</b></div><div><span class="ic">🧢</span><small>연봉예산</small><b>${Ms(I.wage)}</b></div><div><span class="ic">👥</span><small>사용</small><b class="o">${Ms(I.pay)}</b></div></div>`;
  h+=`<div class="mkcard"><div class="row sb"><b>연봉예산 사용 현황 (${mkYear()}시즌)</b><span class="small">예산 ${Ms(I.wage)} <span class="sep">|</span> 사용 ${Ms(I.pay)} <span class="o">(${pct}%)</span></span></div><div class="usebar"><i style="width:${pct}%">${Ms(I.pay)} (선수단 연봉)</i>${pct<85?`<span>${Ms(Math.max(0,I.wageLeft))}<br><small>(잔여)</small></span>`:''}</div><div class="legend small"><span><i class="g"></i> 선수 연봉 ${Ms(I.pay)} (${pct}%)</span><span><i class="x"></i> 잔여 예산 ${Ms(Math.max(0,I.wageLeft))} (${100-pct}%)</span></div>${ut.league==='KR'?`<div class="row" style="gap:6px;margin-top:8px"><span class="small">이적 예산 ${Ms(I.xfer-I.xferLeft)} / ${Ms(I.xfer)}</span><span class="grow"></span><button class="sm ghost" onclick="UI.bShift(1)">이적 3억 → 연봉 1억</button><button class="sm ghost" onclick="UI.bShift(-1)">연봉 1억 → 이적 3억</button></div>`:''}</div>`;
  h+=`<div class="mkcard" style="padding:0">${mkSec('계약상 의무 지출 (확정 기준)','단위: 억 원')}<table class="mkt"><thead><tr><th>시즌</th><th>계약 선수</th><th>연봉 합계</th><th class="hl">보장액 합계</th></tr></thead><tbody>${rows.map(r=>`<tr><td class="tc"><b>${r[0]}</b></td><td class="tc">${r[2]}명</td><td class="tc">${Ms(r[1])}</td><td class="tc hl"><b>${Ms(r[1])}</b></td></tr>`).join('')}</tbody></table></div>`;
  h+=`<div class="mkcard" style="padding:0">${mkSec(`수입 · 지출 현황 (${mkYear()}시즌 누계)`,'단위: 억 원')}<table class="mkt fin"><thead><tr><th class="tn">항목</th><th>금액</th><th>전년 동기 대비</th></tr></thead><tbody>${inc.map(x=>`<tr><td class="tn">${x[0]}</td><td class="tc"><b>${Ms(val(f,x[1],x[2]))}</b></td><td class="tc small">${cmp(x[1],x[2],false)}</td></tr>`).join('')}${out.map(x=>`<tr><td class="tn">${x[0]}</td><td class="tc"><b>${val(f,x[1],x[2])?'-':''}${Ms(val(f,x[1],x[2]))}</b></td><td class="tc small">${cmp(x[1],x[2],true)}</td></tr>`).join('')}</tbody></table></div>`;
  h+=mkBtn2(`<button class="primary big" onclick="UI.go('club','spon')">스폰서 · 수입</button>`,`<button class="ghost big" onclick="UI.go('market','neg')">계약 · 재계약</button>`);return h;}
function renderClub(forced){const ut=SL.userTeam();const sb=ui.sub.club;if(sb==='fac')return hubTabs('club')+renderFacMock(ut);if(sb==='fin')return hubTabs('club')+renderFinMock(ut);return renderClub0(forced);}
