  h+=`<div class="cmp2h">${hd2(a)}<span class="vs">|</span>${b?hd2(b):'<div class="muted small">비교할 우리 선수가 없습니다.</div>'}</div>`;
  h+=`<div class="mktabs3"><button class="${f==='ab'?'on':''}" onclick="UI.set('cmpF','ab')">능력</button><button class="${f==='st'?'on':''}" onclick="UI.set('cmpF','st')">성적</button><button class="${f==='ct'?'on':''}" onclick="UI.set('cmpF','ct')">계약</button></div>`;
  if(!b)return h+`</div></div>`;
  if(f==='ab')h+=`<div class="mkcard">${keys.map(k=>{const x=val(a,k),y=val(b,k);return `<div class="mrow"><b class="${x>=y?'ok':''}">${x}</b><span class="mkbar g rev"><i style="width:${x}%"></i></span><span class="k">${KO[k]||SL.ATTR_KO[k]}</span><span class="mkbar gr"><i style="width:${y}%"></i></span><b class="${y>x?'ok':''}">${y}</b></div>`;}).join('')}</div>`;
  else if(f==='st'){const sa=hasSt(a.cur)?a.cur:(lastSeasonSt(a)||a.cur),sb=hasSt(b.cur)?b.cur:(lastSeasonSt(b)||b.cur);const H=isP?['경기','승','패','ERA','이닝','탈삼진','WHIP']:['경기','타율','홈런','타점','OPS','도루','볼넷'];const ra=statRow(a,sa),rb=statRow(b,sb);h+=`<div class="mkcard" style="padding:0"><table class="mkt"><thead><tr><th>구분</th><th>${esc(a.name)}</th><th>${esc(b.name)}</th></tr></thead><tbody>${H.map((k,i)=>`<tr><td class="tc"><b>${k}</b></td><td class="tc">${ra[i]}</td><td class="tc">${rb[i]}</td></tr>`).join('')}</tbody></table></div>`;}
  else{const ca=a.contract,cb=b.contract;h+=`<div class="mkcard" style="padding:0"><table class="mkt"><thead><tr><th>구분</th><th>${esc(a.name)}</th><th>${esc(b.name)}</th></tr></thead><tbody><tr><td class="tc"><b>연봉</b></td><td class="tc">${ca?Ms(ca.salary):'FA 요구 '+Ms(SL.playerDemand(a,ut))}</td><td class="tc">${cb?Ms(cb.salary):'-'}</td></tr><tr><td class="tc"><b>계약</b></td><td class="tc">${ca?ca.years+'년':'-'}</td><td class="tc">${cb?cb.years+'년':'-'}</td></tr><tr><td class="tc"><b>잠재</b></td><td class="tc">${SL.potText(a)}</td><td class="tc">${SL.potText(b)}</td></tr></tbody></table></div>`;}
  const fit=q=>{const o=SL.calcOvr(q);const lv=SL.BAL.LEVEL_OVR.KR1;return o>=lv+4?['높음','ok']:o>=lv-4?['보통','']:['낮음','bad'];};const fa=fit(a),fb=fit(b);
  h+=`<div class="mkcard" style="padding:0"><table class="kvt2 three"><tr><td>${isP?(a.pos==='SP'?'선발':'불펜'):'주전'} 적합도</td><td class="${fa[1]}"><b>${fa[0]}</b></td><td class="${fb[1]}"><b>${fb[0]}</b></td></tr><tr><td>체력</td><td>${Math.round(a.attrs.stamina||0)}</td><td>${Math.round(b.attrs.stamina||0)}</td></tr><tr><td>연봉</td><td class="ok"><b>${a.contract?Ms(a.contract.salary):Ms(SL.playerDemand(a,ut))}</b></td><td>${b.contract?Ms(b.contract.salary):'-'}</td></tr></table></div>`;
  const da=Math.round(SL.calcOvr(a)-SL.calcOvr(b));const mineA=a.teamId===ut.id;const verdict=da>=3?[mineA?`${SL.josa(a.name,'이','가')} ${b.name}보다 앞섭니다`:`${a.name}: ${isP?(a.pos==='SP'?'선발진':'불펜'):SL.POS_KO[a.pos]} 보강`,'ok']:da<=-3?[`${SL.josa(b.name,'이','가')} 아직 앞섭니다`,'bad']:['비슷한 수준 — 나이·연봉으로 판단',''];
  h+=`<div class="verdict ${verdict[1]}">${verdict[1]==='ok'?'✅':verdict[1]==='bad'?'✖':'➖'} ${esc(verdict[0])}</div>`;
