  h+=pHead2(p,isFA?`<div class="tm"><span class="chip y" style="font-size:12px">FA (자유계약)</span></div>`:fromT?`<div class="tm">${emblem(fromT,48)}<small>${esc(fromT.name)}</small></div>`:'');
